            end
            else begin
                $display("PASS: %0d vs %0d = %s", 
                        a_val, b_val, get_result(g, l, e));
            end
        end
    endtask

    // Task for signed test cases
    task test_case_signed;
        input [3:0] a_val, b_val;
        input exp_g, exp_l, exp_e;
        begin
            a = a_val;
            b = b_val;
            #10;

            // Calculate expected signed values
            integer a_signed = signed_value(a_val);
            integer b_signed = signed_value(b_val);

            bit actual_g = (a_signed > b_signed);
            bit actual_l = (a_signed < b_signed);
            bit actual_e = (a_signed == b_signed);

            if(g !== exp_g || l !== exp_l || e !== exp_e) begin
                $error("Signed: a=%0d(%0d), b=%0d(%0d) failed",
                      a_signed, a_val, b_signed, b_val);
                $display("  Expected: %s", get_result(exp_g, exp_l, exp_e));
                $display("  Got:      %s", get_result(g, l, e));
            end
            else begin
                $display("PASS: %0d(%0d) vs %0d(%0d) = %s",
                        a_signed, a_val, b_signed, b_val, get_result(g, l, e));
            end
        end
    endtask
